package com.hmdp.ai.application.knowledge;
import com.hmdp.ai.application.dto.knowledge.*;import com.hmdp.ai.application.security.AiAccessGuard;import com.hmdp.ai.domain.knowledge.KnowledgeRetriever;import com.hmdp.ai.domain.security.*;import org.springframework.stereotype.Service;
@Service public class KnowledgeSearchApplicationService {private final KnowledgeRetriever retriever;private final AiAccessGuard access;public KnowledgeSearchApplicationService(KnowledgeRetriever retriever,AiAccessGuard access){this.retriever=retriever;this.access=access;}public KnowledgeSearchResponse search(String knowledgeBaseId,KnowledgeSearchRequest request){AiSecurityContext c=access.require(AiPermission.KNOWLEDGE_READ);return new KnowledgeSearchResponse(retriever.retrieve(c.getTenant().getTenantId(),c.getWorkspace().getWorkspaceId(),c.getUserId(),knowledgeBaseId,request.getKnowledgeBaseVersion(),request.getQuery(),request.getTopK()));}}
